/* Heat Guardian R4 PoC 05: streaming wrist HR. See hg_ppg.h. */
#include "hg_ppg.h"
#include <string.h>
#include <math.h>

/* 2nd-order Butterworth band-pass 0.5-4 Hz as two biquads (scipy.signal.butter(1, [0.5,4], 'bandpass', fs) -> sos).
 * Generated by host/make_coeffs.py; one set per sample rate. b = {b0,b1,b2}, a = {a1,a2} (a0 = 1). */
#include "hg_ppg_coeffs.h"   /* produced by host/make_coeffs.py */

#define DC_ALPHA   (1.0f / (1.5f * HG_PPG_FS))   /* tau 1.5 s */
#define ENV_DECAY  (1.0f - 1.0f / (2.0f * HG_PPG_FS))  /* envelope forgets in ~2 s */
#define REFRACTORY_MS 300
#define IBI_MIN_MS 300
#define IBI_MAX_MS 2000
#define DC_MIN_COUNTS 20000.0f   /* test 06: ~1,200 counts with nothing on the window, ~110,000 with skin */
#define PI_MIN_PCT 0.05f         /* wrist PI is 0.1-1 %; below 0.05 % the band is loose or off */
#define PI_MAX_PCT 2.0f          /* above 2 % at the wrist the "pulse" is almost certainly motion */
#define PI_JUMP    3.0f          /* PI 3x its 30-s baseline within seconds = artefact */
#define PI_SLOW_ALPHA (1.0f / (30.0f * HG_PPG_FS))

static inline float biquad(float x, const float *b, const float *a, float *z1, float *z2)
{
  float y = b[0] * x + *z1;
  *z1 = b[1] * x - a[0] * y + *z2;
  *z2 = b[2] * x - a[1] * y;
  return y;
}

void hg_ppg_init(hg_ppg_t *s) { memset(s, 0, sizeof *s); s->dc = -1.0f; }

static uint16_t median_u16(uint16_t *v, int n)
{
  uint16_t t[HG_PPG_MAX_BEATS]; memcpy(t, v, n * sizeof(uint16_t));
  for (int i = 1; i < n; i++) { uint16_t k = t[i]; int j = i - 1; while (j >= 0 && t[j] > k) { t[j + 1] = t[j]; j--; } t[j + 1] = k; }
  return t[n / 2];
}

static void update_window(hg_ppg_t *s, uint32_t now_ms)
{
  /* drop beats older than the window */
  int keep = 0;
  for (int i = 0; i < s->n_beats; i++) if (now_ms - s->beat_ms[i] <= HG_PPG_WIN_MS) s->beat_ms[keep++] = s->beat_ms[i];
  s->n_beats = keep;
  if (s->n_beats < 5) { s->hr_bpm = 0; s->ibi_cv = 1.0f; return; }
  uint16_t ibi[HG_PPG_MAX_BEATS]; int n = 0; float sum = 0, sum2 = 0;
  for (int i = 1; i < s->n_beats; i++) {
    uint32_t d = s->beat_ms[i] - s->beat_ms[i - 1];
    if (d >= IBI_MIN_MS && d <= IBI_MAX_MS) { ibi[n++] = (uint16_t)d; sum += d; sum2 += (float)d * d; }
  }
  if (n < 4) { s->hr_bpm = 0; s->ibi_cv = 1.0f; return; }
  float mean = sum / n, var = sum2 / n - mean * mean;
  s->ibi_cv = mean > 0 ? sqrtf(var > 0 ? var : 0) / mean : 1.0f;
  s->hr_bpm = 60000.0f / median_u16(ibi, n);
}

int hg_ppg_push(hg_ppg_t *s, uint32_t ir, uint32_t now_ms)
{
  float x = (float)ir;
  /* 1. DC tracker and skin check */
  if (s->dc < 0) s->dc = x;
  s->dc += DC_ALPHA * (x - s->dc);
  if (s->dc < DC_MIN_COUNTS) { s->quality = HG_PPG_Q_NO_SKIN; s->hr_bpm = 0; s->n_beats = 0; s->pi_pct = 0; return 0; }

  /* 2. band-pass */
  float y = biquad(x - s->dc, B1, A1, &s->z1a, &s->z2a);
  y = biquad(y, B2, A2, &s->z1b, &s->z2b);

  /* envelope of the filtered signal -> perfusion index and adaptive threshold */
  s->env_hi = (y > s->env_hi) ? y : s->env_hi * ENV_DECAY;
  s->env_lo = (y < s->env_lo) ? y : s->env_lo * ENV_DECAY;
  float pp = s->env_hi - s->env_lo;
  s->pi_pct = 100.0f * pp / s->dc;
  if (s->pi_slow <= 0) s->pi_slow = s->pi_pct;
  s->pi_slow += PI_SLOW_ALPHA * (s->pi_pct - s->pi_slow);

  /* 3. peak: local maximum of y above half the envelope, outside the refractory */
  int beat = 0;
  if (s->prev > s->prev2 && s->prev >= y && s->prev > 0.5f * s->env_hi &&
      now_ms - s->last_peak_ms >= REFRACTORY_MS) {
    uint32_t ibi = now_ms - s->last_peak_ms;
    int ok = 1;
    if (s->last_peak_ms == 0 || ibi > IBI_MAX_MS) {
      /* first beat, or we lost track (> 2 s without a beat, e.g. after an artefact
       * inflated the envelope): restart the rhythm from this beat */
      s->ibi_n = 0; s->rejects = 0;
      s->last_peak_ms = now_ms;
      if (s->n_beats < HG_PPG_MAX_BEATS) s->beat_ms[s->n_beats++] = now_ms;
      beat = 1;
    } else {
      /* 4. IBI validation against the running median */
      if (s->ibi_n >= 4) {
        uint16_t med = median_u16(s->ibi_hist, s->ibi_n);
        if (ibi < 0.7f * med || ibi > 1.3f * med) ok = 0;
      }
      /* un-lock: a real HR step (rest -> walking) looks like a run of rejections.
       * After 4 in a row, trust the new rhythm instead of the old median. */
      if (!ok && ++s->rejects >= 4) { s->ibi_n = 0; s->rejects = 0; ok = 1; }
      if (ok) {
        s->rejects = 0;
        if (s->ibi_n < 8) s->ibi_hist[s->ibi_n++] = (uint16_t)ibi;
        else { memmove(s->ibi_hist, s->ibi_hist + 1, 7 * sizeof(uint16_t)); s->ibi_hist[7] = (uint16_t)ibi; }
        if (s->n_beats < HG_PPG_MAX_BEATS) s->beat_ms[s->n_beats++] = now_ms;
        beat = 1;
      }
      s->last_peak_ms = now_ms;   /* even a rejected peak restarts the refractory */
    }
  }
  s->prev2 = s->prev; s->prev = y;

  /* 5 + 6. window HR and quality, once per beat (cheap enough to do per sample, but no need) */
  if (beat || (now_ms % 1000) == 0) update_window(s, now_ms);
  if (s->pi_pct < PI_MIN_PCT) s->quality = HG_PPG_Q_LOW_PI;
  else if (s->motion || s->pi_pct > PI_MAX_PCT || s->pi_pct > PI_JUMP * s->pi_slow) s->quality = HG_PPG_Q_MOTION;
  else if (s->hr_bpm == 0 || s->ibi_cv > 0.25f) s->quality = HG_PPG_Q_IRREGULAR;
  else s->quality = HG_PPG_Q_OK;
  return beat;
}
